        # Given n <= 2000, O(n^2) space for storing strings might be too much memory (2000*2000 strings is huge).
        # Instead, let's use O(n^2) for lengths and reconstruct by backtracking.

        # dp[i][j] = length of LPS in s[i..j]
        dp = [[0] * n for _ in range(n)]

        # Base case: single characters are palindromes of length 1
        for i in range(n):
            dp[i][i] = 1

        # Fill for lengths 2 to n
        for length in range(2, n + 1):
            for i in range(n - length + 1):
                j = i + length - 1
                if s[i] == s[j]:
                    if length == 2:
                        dp[i][j] = 2
                    else:
                        dp[i][j] = dp[i + 1][j - 1] + 2
                else:
                    dp[i][j] = max(dp[i + 1][j], dp[i][j - 1])

        # Reconstruct the palindrome
        # Use two pointers and backtrack through the dp table
        i, j = 0, n - 1
        left_part = []
        right_part = []

        while i < j:
            if s[i] == s[j]:
                left_part.append(s[i])
                right_part.append(s[j])
                i += 1
                j -= 1
            else:
                # Move in the direction that gives the larger LPS length
