    input_data = sys.stdin.read().splitlines()
    if not input_data:
        return

    try:
        n = int(input_data[0].strip())
    except (ValueError, IndexError):
        return

    # Map characters to their custom ASCII values
    # 'a' -> 26, 'b' -> 25, ..., 'z' -> 1
    # 'A' -> 52, 'B' -> 51, ..., 'Z' -> 27

    char_to_val = {}
    for i in range(26):
        char_to_val[chr(ord('a') + i)] = 26 - i
        char_to_val[chr(ord('A') + i)] = 52 - i

    results = []
    for i in range(1, n + 1):
        if i >= len(input_data):
            break
        s = input_data[i].strip()
        if not s:
            # Empty string case: no characters appear, so condition vacuously true?
            # Let's consider empty string: count of each char is 0.
            # For any char c, count(c) = 0. Is 0 == ASCII(c)? No, since min ASCII is 1.
            # So empty string is "No" unless we define differently.
            # But typically test cases won't be empty. Let's handle it as No.
            results.append("No")
            continue

        from collections import Counter
        counts = Counter(s)
        is_super = True
        for char, count in counts.items():
            if char not in char_to_val:
                # Character not in a-z or A-Z? The problem implies only these.
                # If it appears, its ASCII is not defined in the scheme.
                # Assuming only a-z A-Z appear.
                is_super = False
                break
            if count != char_to_val[char]:
                is_super = False
                break

        if is_super:
            results.append("Yes")
        else:
            results.append("No")

    for res in results:
        print(res)

if __name__ == "__main__":
    solve()
